covarianceBranch_local_bounds.statement:
lemma covarianceBranch_local_bounds (t ξ υ : ℝ)
    (ht : |t| ≤ 1 / 8) (hξ : |ξ - 1 / 2| ≤ 1 / 8) (hυ : |υ - 1 / 2| ≤ 1 / 8) :
    let d := Real.exp t - 1
    let v := ξ * (1 - ξ) * υ * (1 - υ)
    let L := 1 + d * (ξ * (1 - υ) + (1 - ξ) * υ)
    3 / 4 ≤ L ∧ 0 ≤ L ^ 2 - 4 * d ^ 2 * v ∧ |covarianceBranch t ξ υ| ≤ 1 / 24

