    let A := max (1/(3 : ℚ)^seriesBound z) (S-rationalError (q+3))
    let B := S+rationalError (q+3)
    let t := expRegisterCode.run (7*N+15) s
    t.1 = (if right then 88 else 44) ∧ t.2.2 = false ∧
