def mixedTableDenominator (η ζ u q : ℝ) (s : Bool × Bool) : ℝ :=
  let t := 32*η*ζ
  let ξ := 1/2-η*q*localSignField u s
  let υ := 1/2+ζ*localSignField u s
  let d := Real.exp t-1
  let v := ξ*(1-ξ)*υ*(1-υ)
  let L := 1+d*(ξ*(1-υ)+(1-ξ)*υ)
  L+Real.sqrt (L^2-4*d^2*v)

