/-- Interval membership, respecting endpoint inclusion. -/
def intervalSet (B : EffectInterval) : Set ℝ :=
  {t | (B.val.1 < t ∨ (B.val.2.2.1 = true ∧ B.val.1 = t)) ∧
       (t < B.val.2.1 ∨ (B.val.2.2.2 = true ∧ t = B.val.2.1))}

